import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 5), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_parse_transcript_log_skips_comments_and_strips_fields():
    lines = ["", " \t", "  # ignored", " a , 3 , 0 ", " b , 4 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,1,extra", "a,two,1"])
def test_parse_error_includes_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "", "ok,2,1", bad_line])


def test_dedupe_keeps_last_duplicate_id_then_sorts():
    events = parse_transcript_log(["b,9,1", "c,1,1", "a,2,0", "b,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_daily_flag_counts_fills_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,", "e,3,0", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,1,1", "b,5,0", "c,5,0"]), "b": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_reports_handle_ties_and_empty_groups():
    groups = {"d": [{"flagged": False}], "c": [{"flagged": True}], "b": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 2) == ["a", "c"]
    assert top_flagged_groups(groups, 10) == ["a", "c", "d"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 1.0), ("d", 0.0)]


def test_longest_streak_requires_consecutive_positive_counts():
    assert longest_flag_streak([1, 0, 2, 1, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
